    def _raw_mentioned_user_ids(self, message: Any) -> set:
        """Extract user-mention IDs (``<@ID>`` and legacy ``<@!ID>``) from raw content,
        since ``message.mentions`` isn't always populated (mobile/edited/relayed)."""
